// Parity with the server's PDQ hasher.
//
// The fixtures are generated by backend/matching/tests/generate_pdq_fixtures.py from
// pdqhash.compute_dihedral - the very code that hashes reference videos - and are read here
// straight from the backend tree, so there is only one copy and it cannot drift.
// backend/matching/tests/test_pdq_parity.py asserts the same files still match Python.
//
// Every fixture must agree on all eight orientations *and* on quality. A weaker assertion here
// would defeat the point: hashes uploaded by the browser are compared with stored server hashes
// at a distance threshold of 31, so a silent divergence would look like a matching failure.

import { describe, expect, it } from "vitest";

import {
  DIHEDRAL,
  PDQ_HASH_BYTES,
  PDQ_ORIENTATIONS,
  fromHex,
  hammingDistance,
  hashDihedral,
  hashDihedralLuma,
  toHex,
} from "./pdq";

interface Fixture {
  name: string;
  width: number;
  height: number;
  rgb_base64: string;
  quality: number;
  hashes: string[];
}

// Read straight out of the backend tree, inlined by Vite at transform time: no fs, no network,
// and no second copy of the fixtures that could drift from the Python side.
const modules = import.meta.glob<Fixture>(
  "../../../backend/matching/tests/fixtures/pdq/*.json",
  { eager: true, import: "default" },
);

const fixtures: Fixture[] = Object.entries(modules)
  .sort(([left], [right]) => left.localeCompare(right))
  .map(([, fixture]) => fixture);

function rgbOf(fixture: Fixture): Uint8Array {
  const binary = atob(fixture.rgb_base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

describe("PDQ fixtures", () => {
  it("are present and well formed", () => {
    expect(fixtures.length).toBeGreaterThanOrEqual(8);
    for (const fixture of fixtures) {
      expect(fixture.hashes).toHaveLength(PDQ_ORIENTATIONS);
      expect(rgbOf(fixture)).toHaveLength(fixture.width * fixture.height * 3);
    }
  });
});

describe.each(fixtures.map((fixture) => [fixture.name, fixture] as const))(
  "WASM parity: %s",
  (_name, fixture) => {
    it("returns the server's hashes for all eight orientations and the same quality", async () => {
      const { hashes, quality } = await hashDihedral(
        rgbOf(fixture),
        fixture.width,
        fixture.height,
      );

      expect(hashes).toHaveLength(PDQ_ORIENTATIONS);
      expect(hashes.map(toHex)).toEqual(fixture.hashes);
      expect(quality).toBe(fixture.quality);
    });
  },
);

describe("hashDihedral", () => {
  const fixture = fixtures[0];

  it("has a fixture to work with", () => {
    expect(fixture).toBeDefined();
  });

  it("is deterministic across calls", async () => {
    if (!fixture) return;
    const first = await hashDihedral(rgbOf(fixture), fixture.width, fixture.height);
    const second = await hashDihedral(rgbOf(fixture), fixture.width, fixture.height);
    expect(first.hashes.map(toHex)).toEqual(second.hashes.map(toHex));
    expect(first.quality).toBe(second.quality);
  });

  it("returns 32-byte hashes in the documented dihedral order", async () => {
    if (!fixture) return;
    const { hashes } = await hashDihedral(rgbOf(fixture), fixture.width, fixture.height);
    for (const hash of hashes) {
      expect(hash).toBeInstanceOf(Uint8Array);
      expect(hash).toHaveLength(PDQ_HASH_BYTES);
    }
    expect(toHex(hashes[DIHEDRAL.original] as Uint8Array)).toBe(fixture.hashes[0]);
    expect(toHex(hashes[DIHEDRAL.flipMinus1] as Uint8Array)).toBe(fixture.hashes[7]);
  });

  it("rejects buffers that do not match the dimensions", async () => {
    await expect(hashDihedral(new Uint8Array(10), 4, 4)).rejects.toThrow(RangeError);
    await expect(hashDihedral(new Uint8Array(48), 0, 4)).rejects.toThrow(RangeError);
    await expect(hashDihedral(new Uint8Array(48), 4, 1.5)).rejects.toThrow(RangeError);
  });
});

describe("hashDihedralLuma", () => {
  it("equals the RGB path when R=G=B, and differs from a colour frame", async () => {
    const width = 32;
    const height = 32;
    const grey = new Uint8Array(width * height);
    for (let i = 0; i < grey.length; i++) {
      grey[i] = (i * 7) % 256;
    }
    const rgb = new Uint8Array(grey.length * 3);
    for (let i = 0; i < grey.length; i++) {
      const value = grey[i] as number;
      rgb[3 * i] = value;
      rgb[3 * i + 1] = value;
      rgb[3 * i + 2] = value;
    }

    const fromLuma = await hashDihedralLuma(grey, width, height);
    const fromRgb = await hashDihedral(rgb, width, height);
    // R=G=B means both paths see the same luma, up to the last bit of the coefficient sum.
    const distance = hammingDistance(
      fromLuma.hashes[0] as Uint8Array,
      fromRgb.hashes[0] as Uint8Array,
    );
    expect(distance).toBe(0);
    expect(fromLuma.quality).toBe(fromRgb.quality);
  });

  it("checks its input length", async () => {
    await expect(hashDihedralLuma(new Uint8Array(10), 4, 4)).rejects.toThrow(RangeError);
  });
});

describe("hex helpers", () => {
  it("round-trips a fixture hash", () => {
    const hex = fixtures[0]?.hashes[0];
    expect(hex).toBeDefined();
    if (!hex) return;
    expect(toHex(fromHex(hex))).toBe(hex);
  });

  it("rejects malformed input", () => {
    expect(() => fromHex("abc")).toThrow(RangeError);
    expect(() => fromHex("A".repeat(64))).toThrow(RangeError);
    expect(() => toHex(new Uint8Array(8))).toThrow(RangeError);
  });

  it("counts differing bits", () => {
    const zero = new Uint8Array(PDQ_HASH_BYTES);
    const ones = new Uint8Array(PDQ_HASH_BYTES).fill(0xff);
    expect(hammingDistance(zero, zero)).toBe(0);
    expect(hammingDistance(zero, ones)).toBe(256);
    const one = new Uint8Array(PDQ_HASH_BYTES);
    one[3] = 0b1010;
    expect(hammingDistance(zero, one)).toBe(2);
  });
});
